import React from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  LineElement,
  CategoryScale,
  LinearScale,
  PointElement,
  Tooltip,
  Legend
} from 'chart.js';

ChartJS.register(LineElement, CategoryScale, LinearScale, PointElement, Tooltip, Legend);

const RevenueGraph = ({ data }) => {
  const labels = data.bfd?.details[0]?.monthlyData.map(d => d.month) || [];
  const values = data.bfd?.details[0]?.monthlyData.map(d => d.grossRevenue) || [];

  const chartData = {
    labels,
    datasets: [{
      label: 'Gross Revenue',
      data: values,
      borderColor: '#4e73df',
      backgroundColor: 'rgba(78, 115, 223, 0.2)',
      fill: true,
      tension: 0.4
    }]
  };

  return (
    <div style={{ maxWidth: '700px', marginTop: '40px' }}>
      <h3>Monthly Gross Revenue (BFD)</h3>
      <Line data={chartData} />
    </div>
  );
};

export default RevenueGraph;
